files.content:
* {
  box-sizing: border-box;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
h2,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

.cards-list__link {
  color: inherit;
  text-decoration: none;
}

.cards-list__item:hover {
  outline: 2px solid #fd24af;
}

.cards-list {
  width: fit-content;
  margin: auto;
  padding: 40px 0;
  list-style: none;
}

.cards-list__item:not(:last-of-type) {
  margin-bottom: 40px;
}

.card {
  display: flex;
  flex-direction: column;
  max-width: 900px;
  border: 1px solid #000;
  background-color: #fff;
}

.card__image {
  width: 100%;
  object-fit: cover;
  object-position: center;
}

.card__description {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 40px;
  text-align: center;
}

.card__title {
  margin-bottom: 20px;
  font-weight: 800;
  font-size: 31px;
  text-transform: uppercase;
}
.card:not(:has(.card__image)) {
  background-color: #6dc1fd;
}
